tions","secondaryHref":"#faq","rows":[{"icon":"calendar","tags":"60 min","name":"Guidance Call","body":"A single call, just the two of us. We find what's stuck and leave you with one clear next step you can act on this week. Not a sales call.","price":"$120","when":"By appointment","image":"","alt":"","buttonLabel":"Book a time","href":"~/booking"},{"icon":"calendar","tags":"90 min","name":"Emotional Alchemy Session","body":"A longer session to move a stuck feeling into insight and a next step. For when you're ready to go deeper.","price":"$180","when":"By appointment","image":"","alt":"","buttonLabel":"Book a time","href":"~/booking"}],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-services-1","sample":false}},{"type":"NewWorldPlans","props":{"index":"","eyebrow":"Memberships and plans","title":"Keep *coming back.*","lede":"Pick a rhythm. Pause or change it any time.","aside":"Free to join. Pay for what you choose.","featuredLabel":"Most chosen","note":"Pause, change or cancel from your account any time.","rows":[],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-services-2","sample":true}},{"type":"NewWorldAlways","props":{"index":"","eyebrow":"Every visit","title":"Always *true here.*","items":["Checked in at the door","Every session on the calendar","A first visit that is free","Pause any time"],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-services-3","sample":true}},{"type":"NewWorldFaq","props":{"index":"","eyebrow":"Questions","title":"Good to *know.*","lede":"Anything else, ask. A real person answers.","phone":"(760) 235-5031","email":"daniel@danieltyack.com","hours":"Mon to Fri, 9am to 6pm, by appointment","areasLabel":"Where we meet","areas":[],"rows":[],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-services-4","sample":false}},{"type":"NewWorldCloser","props":{"aside":"I won't promise you a new life. What I'll tell you is there's a way through, and it runs through your body, not around it. When you're ready, start with a single call.","title":"When you're *ready*","primaryLabel":"Book an exploratory call","primaryHref":"~/booking","secondaryLabel":"","secondaryHref":"","note":"","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-services-5","sample":false}}]}},{"slug":"about","label":"Our story","seo":{"title":"Our story","description":"Who is behind Your Place."},"comments":[],"doc":{"root":{},"content":[{"type":"NewWorldAboutHero","props":{"eyebrow":"Finding myself","title":"The way back was *through the body*","lead":"There was a stretch when everything I'd built came apart. My business failed, my wife left, my faith crumbled, and the community I'd helped hold disappeared. I kept moving through life, but I wasn't functional. I'd gone quiet in a way I didn't have words for.","chips":[],"primaryLabel":"Book an exploratory call","primaryHref":"~/booking","secondaryLabel":"","secondaryHref":"","image":"https://azsqfeonabsbmemvddqd.supabase.co/storage/v1/object/public/event-media/spaces/9f58e07e-8912-4c3e-8551-d15b275dc768/blocks/1783573226654-jt7v.jpg","alt":"Daniel Tyack sitting outdoors in Encinitas","name":"Daniel Tyack","role":"Coach","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-0","sample":false}},{"type":"NewWorldLongStory","props":{"index":"01","eyebrow":"The story","title":"The way back was *through the body*","paragraphs":["The thing that saved me wasn't more thinking. It was learning to feel what I'd been carrying in my body, and letting my body find the ground again.","Maybe everything came apart at once, a marriage, a business, a faith, and you're standing in the pieces. Maybe you look fine on paper and the days have gone flat. You don't have to explain it well to start.","Everything fell apart at the same time. Grieving, and can't seem to move on. Fine, but not okay. Running on autopilot for a long time. Feeling nothing where there used to be something.","If any of that lands, you're in the right place.","Daniel Tyack works with people who feel stuck, using a technique called Emotional Alchemy to help them access and work through what's in the way. If something's been sitting heavy for a while, this is a place to start moving it."],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-1","sample":false}},{"type":"NewWorldQuote","props":{"label":"In {{person1Name|Your name}}'s words","quote":"We deal in the shadow, where the secret stories hide. We face the demons and find love in the pain.","by":"Daniel Tyack","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-2","sample":false}},{"type":"NewWorldPromises","props":{"index":"02","eyebrow":"What you can count on","title":"Three *promises.*","lede":"","rows":[{"icon":"check","title":"Open doors","body":"Joining is free. No velvet rope, nothing members-only."},{"icon":"users","title":"Same faces","body":"Groups meet at the same time in the same place, so coming back is easy and someone notices when you do."},{"icon":"heart","title":"Bring someone","body":"A first visit with a friend is celebrated. Word of mouth is how this room fills."}],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-3","sample":true}},{"type":"NewWorldTeam","props":{"index":"03","eyebrow":"The team","title":"The people *behind it.*","lede":"Who you will meet.","note":"Real people. Replace these with photos from your room.","rows":[],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-4","sample":true}},{"type":"NewWorldPosts","props":{"index":"04","eyebrow":"Notes","title":"Good to *read.*","lede":"Notes from the room, written by the people in it.","buttonLabel":"","buttonHref":"","rows":[],"register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-5","sample":true}},{"type":"NewWorldCloser","props":{"aside":"I won't promise you a new life. What I'll tell you is there's a way through, and it runs through your body, not around it. When you're ready, start with a single call.","title":"When you're *ready*","primaryLabel":"Book an exploratory call","primaryHref":"~/booking","secondaryLabel":"","secondaryHref":"","note":"","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-about-6","sample":false}}]}},{"slug":"booking","label":"Book","seo":{"title":"Book","description":"Pick a time at Your Place."},"comments":[],"doc":{"root":{},"content":[{"type":"NewWorldBook","props":{"eyebrow":"Save a spot","title":"Pick a night *and come.*","lede":"Live spots, what it costs (often nothing) and a reminder the day before with the facts.","summaryLabel":"Every booking","facts":[],"waysLabel":"Choose a way in","ways":[{"name":"Guidance Call","body":"A single call, just the two of us. We find what's stuck and leave you with one clear next step you can act on this week. Not a sales call.","meta":"$120 · 60 min","href":"~/booking"},{"name":"Emotional Alchemy Session","body":"A longer session to move a stuck feeling into insight and a next step. For when you're ready to go deeper.","meta":"$180 · 90 min","href":"~/booking"}],"timesLabel":"Next open times","useEvents":true,"rows":[],"note":"Change or cancel any time. No one minds.","buttonLabel":"","buttonHref":"","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-booking-0","sample":false}},{"type":"NewWorldAsk","props":{"index":"","eyebrow":"Get in touch","title":"Send me a message","lede":"Not sure where to start? Tell me a little about what's going on. I read every message myself and reply within two business days. This form isn't for emergencies. If you're in crisis, call or text 988.","buttonLabel":"Send message","successMessage":"Thank you. Your message is with me, and I'll reply within two business days. If you'd rather not wait, you can book a call now.","register":"auto","frame":"default","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"},"id":"kit-booking-1","sample":false}}]}},{"slug":"join","label":"Join the list","seo":{"title":"Join the list","description":"Join the list to hear what is coming up."},"comments":[],"doc":{"root":{},"content":[{"type":"SpaceJoinList","props":{"eyebrow":"Stay close","title":"Join the list","body":"Leave your email and we will let you know what is coming up.","submitLabel":"Join the list","successMessage":"You are on the list. Thank you.","id":"kit-join-0","sample":true}}]}}],"theme":"NewWorld"}$j$::jsonb, 'scheduled', null,
